/** One strand: its centreline length and, per point, x, y and half-width on the sheet ([xyh] holds the triples). */
class PenStrand(val length: Float, val xyh: FloatArray) {
    val count: Int get() = xyh.size / 3
}

/** A glyph: its strands in drawing order, decoded on first use. [points] and [checksum] come from the generator, for the tests. */
class PenArt(val name: String, private val data: String, val points: Int, val checksum: Int) {
